<?include("../../common/access.php");include("../../common/autoload.php");$data['page_title']="Setting";$data['page_subtitle']="Slider Add/Edit Form";$data['breadcrumb']=array("Slider List"=>"change_slider","Add | Edit Slider"=>"");  $data['btn']="<input type='button' value='Back to List' class='btn btn-success' onClick='javascript:history.back();'>";if($_REQUEST['delete']){			deleteData("slider",array("id"=>$_REQUEST['delete']));	$data['msg']=$configs['delete_msg'];	  }if($_POST['SBMT_REG']){	//echo "exsfdsjnhf"; exit;    $query=array("title"=>$_POST['title'],	"description"=>$_POST['description'],		"ord"=>$_POST['ord'],	"status"=>$_POST['status'],	"link"=>$_POST['link']);	   	if($_POST['id'])	{	       $r=updateTable("slider",$query,array("id"=>$_POST['id']),array("background"));	       }    else	{	       $r=insertTable("slider",$query,array("background"));       $_POST['id']=$r;     }     if($r)	{             $data['msg']=$configs['success_msg'];    }	else	{	        $data['msg']=$configs['error_msg'];    } }if($_GET['id']){	$data['db_value']=getDataByWhere("slider","*",array("id"=>$_GET['id']));}$data['db_slider']=getQuery("slider");$data['totalslider']=getTotalRow("slider");echo template($data);?>